import { Routes } from "@angular/router";
import { ExamScheduleComponent } from "./exam-schedule/exam-schedule";
import { ExamScheduleAddComponent } from "./exam-schedule/exam-schedule-add/exam-schedule-add";
import { ExamTypeComponent } from "./exam-type/exam-type";
import { ExamTypeAddComponent } from "./exam-type/exam-type-add/exam-type-add";
import { GradeComponent } from "./grade/grade";
import { ResultComponent } from "./result/result";
import { ResultAddComponent } from "./result/result-add/result-add";
import { RoutezFeatureModule } from "@_core/_route";

export const Routez: Routes = new RoutezFeatureModule(
  ['Exam'],
  'feature/exam'
)
.feature(
  ExamScheduleComponent,
  ExamScheduleAddComponent,
  'schedule',
  'Exam Schedule'
)
.feature(
  ExamTypeComponent,
  ExamTypeAddComponent,
  'type',
  'Exam Type'
)
.feature(
  GradeComponent,
  GradeComponent,
  'grade',
  'Grade'
)
.feature(
  ResultComponent,
  ResultAddComponent,
  'result',
  'Result'
)
.build();
